package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"

	"github.com/shopspring/decimal"
)

type SalesRec struct {
	SrId    string
	SrSales decimal.Decimal
}

type TierTable struct {
	TierEntry struct {
		TierLimit decimal.Decimal
		TierRate  decimal.Decimal
	}
}

var WsEofFlag string = "N"
var WsIdx int64 = 0
var WsTier int64 = 0
var WsComm decimal.Decimal = decimal.NewFromInt(0)
var WsTotal decimal.Decimal = decimal.NewFromInt(0)
var WsCount int64 = 0
var WsSalesEd string
var WsRateEd string
var WsCommEd string
var WsTotalEd string

var TierLimits [4]decimal.Decimal
var TierRates [4]decimal.Decimal

var SalesRecVar SalesRec
var salesFile *os.File
var scanner *bufio.Scanner

// helpers

func truncateToField(val decimal.Decimal, intDigits, fracDigits int) decimal.Decimal {
	v := val.Truncate(int32(fracDigits))
	s := v.StringFixed(int32(fracDigits))
	neg := false
	if strings.HasPrefix(s, "-") {
		neg = true
		s = s[1:]
	}
	parts := strings.SplitN(s, ".", 2)
	intStr := parts[0]
	fracStr := ""
	if fracDigits > 0 {
		if len(parts) == 2 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fracDigits)
		}
		if len(fracStr) < fracDigits {
			fracStr = fracStr + strings.Repeat("0", fracDigits-len(fracStr))
		} else if len(fracStr) > fracDigits {
			fracStr = fracStr[:fracDigits]
		}
	}
	if len(intStr) > intDigits {
		intStr = intStr[len(intStr)-intDigits:]
	}
	var recomp string
	if fracDigits > 0 {
		recomp = intStr + "." + fracStr
	} else {
		recomp = intStr
	}
	if neg {
		recomp = "-" + recomp
	}
	d, err := decimal.NewFromString(recomp)
	if err != nil {
		return v
	}
	return d
}

func formatUneditedInt(val int64, digits int) string {
	s := fmt.Sprintf("%d", val)
	if len(s) > digits {
		s = s[len(s)-digits:]
	} else if len(s) < digits {
		s = strings.Repeat("0", digits-len(s)) + s
	}
	return s
}

func formatEdited(pic string, val decimal.Decimal) string {
	dotPos := strings.Index(pic, ".")
	var intPic, fracPic string
	if dotPos == -1 {
		intPic = pic
		fracPic = ""
	} else {
		intPic = pic[:dotPos]
		fracPic = pic[dotPos+1:]
	}
	intDigits := 0
	for _, ch := range intPic {
		if ch == 'Z' || ch == '9' {
			intDigits++
		}
	}
	fracDigits := 0
	for _, ch := range fracPic {
		if ch == 'Z' || ch == '9' {
			fracDigits++
		}
	}
	absVal := val.Abs()
	vTrunc := absVal.Truncate(int32(fracDigits))
	s := vTrunc.StringFixed(int32(fracDigits))
	var intStr, fracStr string
	if fracDigits > 0 {
		parts := strings.SplitN(s, ".", 2)
		intStr = parts[0]
		if len(parts) == 2 {
			fracStr = parts[1]
		} else {
			fracStr = strings.Repeat("0", fracDigits)
		}
		if len(fracStr) < fracDigits {
			fracStr = fracStr + strings.Repeat("0", fracDigits-len(fracStr))
		}
	} else {
		intStr = s
		fracStr = ""
	}
	var intDigitsPadded string
	if len(intStr) > intDigits {
		intDigitsPadded = intStr[len(intStr)-intDigits:]
	} else {
		intDigitsPadded = strings.Repeat("0", intDigits-len(intStr)) + intStr
	}
	picRunes := []rune(pic)
	outRunes := make([]rune, len(picRunes))
	copy(outRunes, picRunes)
	di := 0
	fi := 0
	for i, ch := range picRunes {
		if ch == 'Z' || ch == '9' {
			if dotPos != -1 && i > dotPos {
				if fi < len(fracStr) {
					outRunes[i] = rune(fracStr[fi])
					fi++
				} else {
					outRunes[i] = '0'
				}
			} else {
				// integer part
				if dotPos == -1 || i < dotPos {
					outRunes[i] = rune(intDigitsPadded[di])
					di++
				}
			}
		} else if ch == ',' || ch == '.' {
			outRunes[i] = ch
		}
	}
	// Z suppression
	var digitPos []int
	for i, ch := range picRunes {
		if (ch == 'Z' || ch == '9') && (dotPos == -1 || i < dotPos) {
			digitPos = append(digitPos, i)
		}
	}
	firstNZ := len(intDigitsPadded)
	for idx, ch := range intDigitsPadded {
		if ch != '0' {
			firstNZ = idx
			break
		}
	}
	for k, pos := range digitPos {
		placeholder := picRunes[pos]
		if k < firstNZ {
			if placeholder == 'Z' {
				outRunes[pos] = ' '
			}
		}
	}
	// comma suppression
	for i, ch := range picRunes {
		if ch == ',' && (dotPos == -1 || i < dotPos) {
			allSuppressed := true
			for _, dp := range digitPos {
				if dp < i {
					if outRunes[dp] != ' ' {
						allSuppressed = false
						break
					}
				}
			}
			if allSuppressed {
				outRunes[i] = ' '
			} else {
				outRunes[i] = ','
			}
		}
	}
	return string(outRunes)
}

// paragraphs

func initPara() {
	TierLimits[0] = decimal.RequireFromString("1000.00")
	TierRates[0] = decimal.RequireFromString("2.50")
	TierLimits[1] = decimal.RequireFromString("5000.00")
	TierRates[1] = decimal.RequireFromString("4.00")
	TierLimits[2] = decimal.RequireFromString("20000.00")
	TierRates[2] = decimal.RequireFromString("5.50")
	TierLimits[3] = decimal.RequireFromString("999999.99")
	TierRates[3] = decimal.RequireFromString("7.25")
	WsComm = decimal.NewFromInt(0)
	WsTotal = decimal.NewFromInt(0)
}

func readPara() {
	if scanner == nil {
		WsEofFlag = "Y"
		return
	}
	if !scanner.Scan() {
		if err := scanner.Err(); err != nil {
			fmt.Fprintf(os.Stderr, "scan error: %v\n", err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
		return
	}
	line := scanner.Text()
	if len(line) < 12 {
		line = line + strings.Repeat(" ", 12-len(line))
	} else if len(line) > 12 {
		line = line[:12]
	}
	srId := line[0:4]
	srSalesRaw := line[4:12]
	var b strings.Builder
	for _, ch := range srSalesRaw {
		if ch >= '0' && ch <= '9' {
			b.WriteRune(ch)
		} else {
			b.WriteRune('0')
		}
	}
	digitsStr := b.String()
	intVal, err := decimal.NewFromString(digitsStr)
	if err != nil {
		intVal = decimal.NewFromInt(0)
	}
	srSales := intVal.Shift(-2)
	srSales = truncateToField(srSales, 6, 2)
	SalesRecVar.SrId = srId
	SalesRecVar.SrSales = srSales
	WsEofFlag = "N"
}

func processPara() {
	WsTier = 0
	WsIdx = 1
	for WsIdx <= 4 && WsTier == 0 {
		if SalesRecVar.SrSales.Cmp(TierLimits[WsIdx-1]) <= 0 {
			WsTier = WsIdx
		}
		WsIdx++
	}
	tierRate := TierRates[WsTier-1]
	raw := SalesRecVar.SrSales.Mul(tierRate).Shift(-2)
	rounded := raw.Round(2)
	WsComm = truncateToField(rounded, 6, 2)
	WsTotal = WsTotal.Add(WsComm)
	WsTotal = truncateToField(WsTotal, 9, 2)
	WsCount = WsCount + 1
	WsCount = WsCount % 1000
	WsSalesEd = formatEdited("ZZZ,ZZ9.99", SalesRecVar.SrSales)
	WsRateEd = formatEdited("9.99", tierRate)
	WsCommEd = formatEdited("ZZZ,ZZ9.99", WsComm)
	tierStr := formatUneditedInt(WsTier, 1)
	srId := SalesRecVar.SrId
	if len(srId) < 4 {
		srId = srId + strings.Repeat(" ", 4-len(srId))
	} else if len(srId) > 4 {
		srId = srId[:4]
	}
	line := srId + " T" + tierStr + " " + WsSalesEd + " " + WsRateEd + "% " + WsCommEd
	fmt.Println(line)
	readPara()
}

func summaryPara() {
	WsTotalEd = formatEdited("ZZZ,ZZZ,ZZ9.99", WsTotal)
	countStr := formatUneditedInt(WsCount, 3)
	line := "REPS: " + countStr + " TOTAL: " + WsTotalEd
	fmt.Println(line)
}

func mainPara() {
	initPara()
	f, err := os.Open("input.dat")
	if err != nil {
		fmt.Fprintf(os.Stderr, "error opening input.dat: %v\n", err)
		os.Exit(1)
	}
	salesFile = f
	defer f.Close()
	scanner = bufio.NewScanner(f)
	readPara()
	for WsEofFlag != "Y" {
		processPara()
	}
	summaryPara()
}

func main() {
	mainPara()
}
